        except Exception:
            pass

    if ids is None:
        if coords is not None:
            cl = as_list(coords)
            if cl is not None:
                ids = list(range(len(cl)))
                coords = cl
        elif demands is not None:
            dl = as_list(demands)
            if dl is not None:
                ids = list(range(len(dl)))
                demands = dl
        else:
            n = get(instance, ["n", "num_nodes", "size"], 0)
            try:
                n = int(n)
            except Exception:
                n = 0
            ids = list(range(n))

    n = len(ids)
    if n <= 1:
        return []

    demands = as_list(demands)
    if demands is None:
        demands = [0] * n
    if len(demands) < n:
        demands = demands + [0] * (n - len(demands))

    coords = as_list(coords)
    if coords is not None and len(coords) < n:
        coords = coords + [None] * (n - len(coords))

    dist_matrix = as_list(dist_matrix)

    id_to_idx = {}
    for i, cid in enumerate(ids):
        id_to_idx[cid] = i

    depot_idx = id_to_idx.get(depot_id, 0)

    if capacity is None:
        total = 0
        for i in range(n):
            if ids[i] != depot_id:
                try:
                    total += float(demands[i])
                except Exception:
                    pass
        capacity = total if total > 0 else 1
    try:
        capacity = float(capacity)
    except Exception:
        capacity = 1.0

    def dist_idx(i, j):
        if dist_matrix is not None:
            try:
                return float(dist_matrix[i][j])
            except Exception:
                pass
        a = coords[i] if coords is not None and i < len(coords) else None
        b = coords[j] if coords is not None and j < len(coords) else None
        if a is not None and b is not None and is_seq(a) and is_seq(b):
            try:
                ax = float(a[0]); ay = float(a[1])
                bx = float(b[0]); by = float(b[1])
                dx = ax - bx
                dy = ay - by
                return (dx * dx + dy * dy) ** 0.5
            except Exception:
                pass
        ii = i
        jj = j
        if ii > jj:
            ii, jj = jj, ii
        return float(jj - ii)

    def radial_of(i):
        return dist_idx(depot_idx, i)

    def angle_key(i):
        if coords is None:
            return (0, 0, i)
        try:
            p = coords[i]
            d = coords[depot_idx]
            if not is_seq(p) or not is_seq(d):
                return (0, radial_of(i), i)
            dx = float(p[0]) - float(d[0])
            dy = float(p[1]) - float(d[1])
            # Deterministic surrogate for polar angle without imports.
            if dx == 0 and dy == 0:
                return (0, 0, i)
            quad = 0
            if dy < 0:
                quad += 2
            if dx < 0:
                quad += 1
            slope = dy / dx if dx != 0 else (1e18 if dy > 0 else -1e18)
            return (quad, slope, radial_of(i), i)
        except Exception:
            return (0, radial_of(i), i)

    customers_idx = []
    for i in range(n):
        if ids[i] != depot_id:
            customers_idx.append(i)

    unassigned = set(customers_idx)
    routes = []

    while unassigned:
        seed = None
        seed_key = None
        for i in unassigned:
            d = 0.0
            try:
                d = float(demands[i])
            except Exception:
                d = 0.0
            key = (radial_of(i), angle_key(i), d, -i)
            if seed is None or key > seed_key:
                seed = i
                seed_key = key

        route = [seed]
        unassigned.remove(seed)
        load = float(demands[seed]) if seed < len(demands) else 0.0

        while unassigned:
            best = None
            best_key = None
            for cand in unassigned:
                d = float(demands[cand]) if cand < len(demands) else 0.0
                if load + d > capacity:
                    continue
                for pos in range(len(route) + 1):
                    left = depot_idx if pos == 0 else route[pos - 1]
                    right = depot_idx if pos == len(route) else route[pos]
                    delta = dist_idx(left, cand) + dist_idx(cand, right) - dist_idx(left, right)
                    key = (delta, -d, radial_of(cand), angle_key(cand), cand)
                    if best is None or key < best_key:
                        best = (cand, pos, d)
                        best_key = key
            if best is None:
                break
            cand, pos, d = best
            route.insert(pos, cand)
            load += d
            unassigned.remove(cand)

        routes.append([ids[i] for i in route])

    # Safety: ensure every customer appears exactly once, append singletons if needed.
    seen = {}
    for r in routes:
        for cid in r:
            seen[cid] = seen.get(cid, 0) + 1

    for i in customers_idx:
        cid = ids[i]
        if seen.get(cid, 0) == 0:
            routes.append([cid])

    return routes
